def max_aggregate(records):
    totals = {}
    for name, value in records:
        totals[name] = totals.get(name, 0) + value
    if not totals:
        raise ValueError("max_aggregate() arg is an empty sequence")
    return max(totals.items(), key=lambda item: item[1])
```

